package com.citacloud.springboot.contacloud.app.services;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.repositories.*;
import com.citacloud.springboot.contacloud.app.reports.pos.CashVoucherPrintDocument.*;
import com.citacloud.springboot.contacloud.app.security.*;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.test.util.ReflectionTestUtils;
class CashVoucherDocumentServiceTest {
 UUID tenant=UUID.randomUUID(),company=UUID.randomUUID(),branch=UUID.randomUUID(),cash=UUID.randomUUID(),id=UUID.randomUUID(),userId=UUID.randomUUID();
 ValeCajaRepository vouchers=mock(ValeCajaRepository.class);CashVoucherDocumentService service=new CashVoucherDocumentService(vouchers);
 SesionCaja session;ValeCaja voucher;Empresa business;Usuario cashier;
 @BeforeEach void fixture(){
  login(tenant,company,true,Set.of());session=mock(SesionCaja.class);when(session.getTenantId()).thenReturn(tenant);when(session.getEmpresaId()).thenReturn(company);when(session.getCajaId()).thenReturn(cash);when(session.getSucursalId()).thenReturn(branch);when(session.getId()).thenReturn(UUID.randomUUID());when(session.getMonedaId()).thenReturn(UUID.randomUUID());
  var c=mock(Caja.class);when(c.getNombre()).thenReturn("Caja histórica");when(session.getCaja()).thenReturn(c);var b=mock(Sucursal.class);when(b.getNombre()).thenReturn("Principal histórica");when(session.getSucursal()).thenReturn(b);var m=mock(Moneda.class);when(m.getCodigoIso()).thenReturn("DOP");when(session.getMoneda()).thenReturn(m);
  cashier=mock(Usuario.class);when(cashier.getNombre()).thenReturn("Juan");when(cashier.getApellido()).thenReturn("Pérez");when(session.getUsuarioApertura()).thenReturn(cashier);
  var concept=mock(ConceptoValeCaja.class);when(concept.getId()).thenReturn(UUID.randomUUID());when(concept.getNombre()).thenReturn("Materiales de oficina");
  voucher=new ValeCaja(tenant,company,session,concept,"VAL-000025","Carlos Rodríguez",new BigDecimal("2500.0000"),"REF-25","Uso administrativo",userId,"María Rodríguez",UUID.randomUUID(),"Empresa histórica","124543678","Dirección histórica","8095551234",null,null);ReflectionTestUtils.setField(voucher,"id",id);ReflectionTestUtils.setField(voucher,"fechaHora",OffsetDateTime.parse("2026-11-02T15:24:00Z"));when(vouchers.findByIdAndTenantIdAndEmpresaId(id,tenant,company)).thenReturn(Optional.of(voucher));
  business=mock(Empresa.class);when(business.getId()).thenReturn(company);when(business.getTenantId()).thenReturn(tenant);when(business.getPaisCodigo()).thenReturn("DO");when(business.getZonaHoraria()).thenReturn("America/Santo_Domingo");
 }
 void login(UUID t,UUID c,boolean all,Set<UUID> branches){var p=new TenantPrincipal(userId,t,c,null,"DEMO","María Rodríguez","maria","",true,all,branches,Set.of("vales_caja.ver","vales_caja.imprimir"));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,p.getAuthorities()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void capturesConfirmedExplicitCashOutWithoutChangingAmounts(){CashVoucherDocumentService.conservar(voucher,session,business);var d=service.documento(voucher);assertThat(d.createdDateTime()).isEqualTo(LocalDateTime.of(2026,11,2,11,24));assertThat(d.movementType()).isEqualTo(MovementType.CASH_OUT);assertThat(d.paymentMethod()).isEqualTo("Efectivo");assertThat(d.amount()).isEqualByComparingTo("2500");assertThat(d.cashier()).isEqualTo("Juan Pérez");assertThat(d.performedBy()).isEqualTo("María Rodríguez");assertThat(d.relatedParty().label()).isEqualTo(PartyLabel.BENEFICIARIO);assertThat(d.relatedParty().name()).isEqualTo("Carlos Rodríguez");assertThat(voucher.getEstado()).isEqualTo(EstadoValeCaja.CONFIRMED);}
 @Test void reprintIsHistoricalAndNeverWritesToRepository(){CashVoucherDocumentService.conservar(voucher,session,business);String json=voucher.getDocumentoPos();byte[] before=service.generar(id).contenido();when(business.getNombre()).thenReturn("Nombre nuevo");when(business.getZonaHoraria()).thenReturn("Asia/Tokyo");when(cashier.getNombre()).thenReturn("Otro nombre");assertThat(service.generar(id).contenido()).isEqualTo(before);assertThat(voucher.getDocumentoPos()).isEqualTo(json);assertThatThrownBy(()->CashVoucherDocumentService.conservar(voucher,session,business)).isInstanceOf(IllegalStateException.class);verify(vouchers,never()).save(any());}
 @Test void legacyUsesOnlyStoredSnapshotsAndRecordedOffset(){var d=service.documento(voucher);assertThat(d.company().name()).isEqualTo("Empresa histórica");assertThat(d.createdDateTime()).isEqualTo(LocalDateTime.of(2026,11,2,15,24));assertThat(d.company().countryCode()).isEqualTo("XX");assertThat(d.cashier()).isNull();assertThat(d.movementType()).isEqualTo(MovementType.CASH_OUT);assertThat(voucher.getDocumentoPos()).isNull();verifyNoInteractions(business,cashier);}
 @Test void tenantCompanyBranchAndSessionAreValidated(){CashVoucherDocumentService.conservar(voucher,session,business);login(UUID.randomUUID(),company,true,Set.of());assertThatThrownBy(()->service.documento(voucher)).isInstanceOf(RecursoNoEncontradoException.class);login(tenant,UUID.randomUUID(),true,Set.of());assertThatThrownBy(()->service.documento(voucher)).isInstanceOf(RecursoNoEncontradoException.class);login(tenant,company,false,Set.of(UUID.randomUUID()));assertThatThrownBy(()->service.cargar(id)).isInstanceOf(RecursoNoEncontradoException.class);login(tenant,company,true,Set.of());when(session.getCajaId()).thenReturn(UUID.randomUUID());assertThatThrownBy(()->CashVoucherDocumentService.conservar(voucher,session,business)).isInstanceOf(RecursoNoEncontradoException.class);}
 @Test void corruptSnapshotDoesNotFallbackOrMutateVoucher(){voucher.conservarDocumentoPos("{}");assertThatThrownBy(()->service.generar(id)).isInstanceOf(ReglaNegocioException.class);assertThat(voucher.getDocumentoPos()).isEqualTo("{}");assertThat(voucher.getImporte()).isEqualByComparingTo("2500");assertThat(voucher.getEstado()).isEqualTo(EstadoValeCaja.CONFIRMED);}
 @Test void cancellationIsPrintedWithoutRewritingOriginalSnapshot()throws Exception{CashVoucherDocumentService.conservar(voucher,session,business);String json=voucher.getDocumentoPos();voucher.anular("Error de registro",userId,"María",UUID.randomUUID());try(var pdf=org.apache.pdfbox.Loader.loadPDF(service.generar(id).contenido())){assertThat(new org.apache.pdfbox.text.PDFTextStripper().getText(pdf)).contains("ANULADO","Error de registro","2,500.00");}assertThat(voucher.getDocumentoPos()).isEqualTo(json);assertThat(voucher.getEstado()).isEqualTo(EstadoValeCaja.VOIDED);}
 @Test void renderFailureCannotUndoFinancialState(){ReflectionTestUtils.setField(voucher,"empresaNombre","Empresa \uD83D\uDE00");CashVoucherDocumentService.conservar(voucher,session,business);String json=voucher.getDocumentoPos();assertThatThrownBy(()->service.generar(id)).isInstanceOf(ReglaNegocioException.class);assertThat(voucher.getDocumentoPos()).isEqualTo(json);assertThat(voucher.getEstado()).isEqualTo(EstadoValeCaja.CONFIRMED);assertThat(voucher.getImporte()).isEqualByComparingTo("2500");}
}
